function A = AF7R52_GENERALITY_AUDIT\nassert(evalin('base','exist(''D38'',''var'')==1'), ...\n    'Run: D38 = AF7R38_SPEED_ROOTCAUSE_AUDIT; first.');\nD38=evalin('base','D38'); P=D38.pipeline;\nfprintf('\n====================================================================================================\n');\nfprintf(' AF7R52 | GENERAL-C7 WORLD-3D PHASE / CORRIDOR AUDIT\n');\nfprintf('====================================================================================================\n');\nF={ ...\n 'predeadline_candidate_success','predeadline_candidate_family', ...\n 'predeadline_uav_speed','predeadline_payload_speed','predeadline_qdot', ...\n 'predeadline_c7_exact','predeadline_speed_pass_count','predeadline_rejoin_pass_count','predeadline_geometry_test_count', ...\n 'r47_active_base_replan_count','r47_nonaffine_base_count', ...\n 'r51_phase_alpha','r51_phase_delay_s','r51_phase_exit_time_s', ...\n 'r52_phase_episode_count','r52_phase_episode_rebuild_fail_count', ...\n 'r52_corridor_row_count','r52_support_plane_fail_count', ...\n 'r52_spatial_qp_solution_count','r52_rejoin_time_trial_count','r52_selected_spatial_rejoin_s', ...\n 'r37_side_assignments','r37_spatial_qp_solutions','r37_exact_c7_candidates','r51_tangent_certified_count', ...\n 'r37_best_total_velocity_ub','r37_best_accel_ub','r37_best_jerk_ub', ...\n 'native_episode_ms','native_hessian_ms','native_corridor_ms','native_qp_ms','native_candidate_build_ms','native_total_ms', ...\n 'last_stage1_ms','last_stage2_ms','last_stage3_ms'};\nfor k=1:numel(F)\n f=F{k};\n if isfield(P,f)\n  v=P.(f);\n  if isnumeric(v)||islogical(v)\n   if isscalar(v),fprintf('%-58s = %.17g\n',f,double(v)); else,fprintf('%-58s = %s\n',f,mat2str(double(v),17));end\n  else,fprintf('%-58s = %s\n',f,char(string(v)));end\n else,fprintf('%-58s = <NOT EXPOSED>\n',f);end\nend\nfprintf('\nContract:\n');\nfprintf(' - unsafe episodes are rebuilt on the actual phase-composed reference; no warped-old-episode approximation.\n');\nfprintf(' - spatial correction is world-3D C7; no straight/affine/fixed-lateral-plane assumption.\n');\nfprintf(' - support-plane numerical failure fails closed; no alternative trajectory-family fallback.\n');\nfprintf(' - phase delay preserves the old spatial path without same-clock catch-up.\n');\nfprintf('====================================================================================================\n');\nA=P;assignin('base','R52A',A);\nend\n